//! Embed the payload into the binary, so one executable installs the mod without a folder beside it.
//!
//! The payload (`app/payload`, 27 MB, 1 169 files: the module of each variant, the IPS files, the config block, the
//! romfs overlays, the enemy packs) is data, not code, and it is generated by `tools/ci_payload.py` — it is not in the
//! repository. When it is there at build time this script writes one `include_bytes!` per file into the crate, and the
//! app unpacks them into the user's data folder the first time it needs them (`embedded::ensure`). Without the folder
//! (a checkout that never ran the payload tool) nothing is embedded and the app looks for `payload/` beside itself,
//! which is how it ran before.
//!
//! `SHB_PAYLOAD_DIR` names another payload folder; `SHB_NO_EMBED_PAYLOAD=1` builds without it.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-env-changed=SHB_PAYLOAD_DIR");
    println!("cargo:rerun-if-env-changed=SHB_NO_EMBED_PAYLOAD");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
    let target = out.join("payload_embed.rs");
    if std::env::var_os("SHB_NO_EMBED_PAYLOAD").is_some() {
        write_empty(&target);
        return;
    }
    let root = std::env::var_os("SHB_PAYLOAD_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            Path::new(&std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"))
                .join("..")
                .join("..")
                .join("..")
                .join("app")
                .join("payload")
        });
    if !root.join("romfs").is_dir() && !root.join("standalone").is_dir() {
        write_empty(&target);
        return;
    }
    let mut files: Vec<(String, PathBuf, u64)> = Vec::new();
    collect(&root, &root, &mut files);
    files.sort_by(|a, b| a.0.cmp(&b.0));
    if files.is_empty() {
        write_empty(&target);
        return;
    }
    // The stamp names the folder the app unpacks into, so a rebuilt payload never mixes with the previous one. It
    // hashes the *content*: two builds of the same module differ (a build id inside the NSO), and names and sizes
    // would not notice.
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for (name, path, size) in &files {
        for byte in name.as_bytes().iter().chain(size.to_le_bytes().iter()) {
            hash ^= *byte as u64;
            hash = hash.wrapping_mul(0x100_0000_01b3);
        }
        if let Ok(data) = std::fs::read(path) {
            for byte in data.iter().step_by(7) {
                hash ^= *byte as u64;
                hash = hash.wrapping_mul(0x100_0000_01b3);
            }
        }
    }
    let mut text = String::with_capacity(1024 * files.len());
    let _ = writeln!(
        text,
        "/// The payload embedded at build time: {} files.",
        files.len()
    );
    let _ = writeln!(text, "pub const STAMP: &str = \"{hash:016x}\";");
    let _ = writeln!(text, "pub static FILES: &[(&str, &[u8])] = &[");
    for (name, path, _) in &files {
        let literal = path.to_string_lossy().replace('\\', "/");
        let _ = writeln!(text, "    ({name:?}, include_bytes!({literal:?})),");
    }
    let _ = writeln!(text, "];");
    std::fs::write(&target, text).expect("write payload_embed.rs");
    println!("cargo:rustc-cfg=shb_embedded_payload");
    println!("cargo:rerun-if-changed={}", root.display());
}

fn write_empty(target: &Path) {
    std::fs::write(
        target,
        "/// Nothing embedded: the app looks for `payload/` beside itself.\npub const STAMP: &str = \"\";\npub static FILES: &[(&str, &[u8])] = &[];\n",
    )
    .expect("write payload_embed.rs");
}

fn collect(root: &Path, dir: &Path, out: &mut Vec<(String, PathBuf, u64)>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(meta) = entry.metadata() else { continue };
        if meta.is_dir() {
            collect(root, &path, out);
            continue;
        }
        let Ok(relative) = path.strip_prefix(root) else {
            continue;
        };
        let name = relative.to_string_lossy().replace('\\', "/");
        out.push((name, path.clone(), meta.len()));
    }
}
